  ?person wdt:P19 ?place .        # place of birth
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?place ?placeLabel

SELECT ?property ?propertyLabel ?propertyDescription WHERE {
  ?property a wikibase:Property .
  FILTER NOT EXISTS { 
    ?property rdfs:label ?label .
    FILTER(LANG(?label) = "es")
  }
  FILTER NOT EXISTS {
    ?property schema:description ?description .
    FILTER(LANG(?description) = "es")
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT (COUNT(DISTINCT ?statement) AS ?count) WHERE {
  ?statement a wikibase:Statement ;
             prov:wasDerivedFrom ?reference .
  ?reference wdt:P356 ?doi .
}

SELECT ?image ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5 . # instance of human (not needed, but to ensure it's a drawing)
  ?item wdt:P180 ?cathedral . # depicts a cathedral
  ?cathedral wdt:P31 wd:Q2977 . # instance of cathedral
  ?cathedral wdt:P17 wd:Q142 . # country France
  ?item wdt:P18 ?image . # has image
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?ingredient ?ingredientLabel (COUNT(?sandwich) AS ?count) WHERE {
  ?sandwich wdt:P31 wd:Q28803 ;  # instance of sandwich
            wdt:P527 ?ingredient .   # has part ingredient
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
GROUP BY ?ingredient ?ingredientLabel
ORDER BY DESC(?count)
LIMIT 10

SELECT ?item ?itemLabel ?inventoryNumber WHERE {
  ?item wdt:P217 ?inventoryNumber.
  FILTER NOT EXISTS { ?item wdt:P195 ?collection. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?cityhall ?cityhallLabel ?address WHERE {
  ?cityhall wdt:P31 wd:Q251620 ;   # instance of city hall
            wdt:P17 wd:Q29 ;       # country Spain
            wdt:P6375 ?address .   # street address
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?city ?cityLabel ?population ?osmRelationId WHERE {
  ?city wdt:P31 wd:Q7930989;  # instance of city or town
        wdt:P17 wd:Q35;       # country Denmark
        wdt:P1082 ?population; # population
        wdt:P402 ?osmRelationId. # OSM relation ID
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?country ?countryLabel WHERE {
  ?country wdt:P31 wd:Q6256 .
  FILTER NOT EXISTS {
    ?municipality wdt:P31 wd:Q15284 ; wdt:P131 wd:Q3995 .
    FILTER NOT EXISTS { ?country wdt:P47 ?municipality . }
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?photo ?photoLabel WHERE {
  ?photo wdt:P31 wd:Q125191 .   # instance of photograph
  ?photo wdt:P180 ?work .       # depicts something
  ?photo wdt:P577 ?date .       # point in time
  ?photo wdt:P195 wd:Q302028 .  # collection: French National Archives
  ?work wdt:P31 wd:Q207250 .    # depicted is a restoration work
  FILTER(YEAR(?date) >= 1801 && YEAR(?date) <= 1900)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?date ?stateLabel ?cases WHERE {
  wd:Q668 wdt:P31 wd:Q3624078. # COVID-19 is a disease
  ?case wdt:P585 ?date ;
        wdt:P276 ?location ;
        wdt:P1603 ?cases .
  ?location wdt:P17 wd:Q668 . # India
  ?location wdt:P131 ?state .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?entity ?entityLabel WHERE {
  { ?entity wdt:P31 wd:Q8513 } UNION { ?entity wdt:P31 wd:Q212805 }.
  FILTER NOT EXISTS { ?entity wdt:P856 ?url }.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?entityLabel

SELECT ?monument ?monumentLabel ?location ?type ?typeLabel ?color WHERE {
  ?monument wdt:P31 wd:Q219321 ; # instance of cultural monument
            wdt:P17 wd:Q215 ;     # country Slovenia
            wdt:P625 ?location .  # coordinate location
  OPTIONAL { ?monument wdt:P31 ?type . } # type of monument
  BIND(IF(?type = wd:Q219321, "red", 
          IF(?type = wd:Q41176, "blue", 
          IF(?type = wd:Q4989906, "green", "gray"))) AS ?color)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?writer ?writerLabel ?signature WHERE {
  ?writer wdt:P106 wd:Q36180 ;
          wdt:P31 wd:Q5 ;
          wdt:P21 wd:Q6581072 ;
          wdt:P1416 wd:Q150 .
  OPTIONAL { ?writer wdt:P109 ?signature . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?artwork ?artworkLabel ?image WHERE {
  { ?artwork wdt:P31 wd:Q3305213 } UNION { ?artwork wdt:P31 wd:Q838948 }.
  ?artwork wdt:P921 wd:Q405.
  OPTIONAL { ?artwork wdt:P18 ?image. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?grandchild ?grandchildLabel WHERE {
  wd:Q1339 wdt:P26 wd:Q57328 .   # Johann Sebastian Bach married Maria Barbara Bach
  wd:Q1339 wdt:P40 ?child .      # Johann Sebastian Bach has children
  ?child wdt:P22 wd:Q1339 .      # Child's father is Johann Sebastian Bach
  ?child wdt:P25 wd:Q57328 .     # Child's mother is Maria Barbara Bach
  ?grandchild wdt:P22 ?child .   # Grandchild's father is that child
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX dct: <http://purl.org/dc/terms/>

SELECT ?lexeme ?lemma WHERE {
  ?lexeme a wikibase:Lexeme ;
          dct:language wd:Q1860 ;
          wikibase:lemma ?lemma .
  FILTER(STRSTARTS(UCASE(?lemma), "F") && STRLEN(?lemma) = 5)
}

SELECT ?tree ?treeLabel ?coord ?image WHERE {
  ?tree wdt:P31 wd:Q10884 ;          # instance of tree
        wdt:P17 wd:Q219 ;            # country: Bulgaria
        wdt:P625 ?coord .            # coordinate location
  OPTIONAL { ?tree wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?inventor ?inventorLabel WHERE {
  ?inventor wdt:P106 wd:Q205375 ;
            wdt:P102 wd:Q29468 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q35127.
  FILTER NOT EXISTS { ?item wdt:P856 ?website. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?organism ?organismLabel WHERE {
  ?organism wdt:P31 wd:Q16521 .  # instance of taxon
  ?organism wdt:P105 wd:Q7432 .  # has rank species (or other appropriate rank)
  ?organism wdt:P171* wd:Q177 .  # subclass of bacteria (or other relevant phyla)
  ?organism wdt:P703 wd:Q105301 . # found in taxon Homo sapiens
  ?organism wdt:P927 wd:Q148 .   # anatomical location vagina
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?item ?itemLabel ?rkdimages ?image WHERE {
  ?item wdt:P31 wd:Q3305213 .
  ?item wdt:P423 ?rkdimages .
  OPTIONAL { ?item wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
}
LIMIT 100

SELECT ?director ?directorLabel (COUNT(?film) AS ?collaborations) WHERE {
  ?film wdt:P31 wd:Q11424 ;
        wdt:P57 ?director .
  ?film wdt:P161 wd:Q3165981 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?director ?directorLabel
ORDER BY DESC(?collaborations)

SELECT ?property ?propertyID ?propertyDescription WHERE {
  ?property a wikibase:Property .
  BIND(STRAFTER(STR(?property), "http://www.wikidata.org/entity/") AS ?propertyID)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?propertyID

SELECT ?cave ?caveLabel ?coords WHERE {
  ?cave wdt:P31 wd:Q12198223 ;   # instance of cave with prehistoric art
        wdt:P625 ?coords .       # coordinate location
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?person ?personLabel WHERE {
  ?person wdt:P21 wd:Q6581072 .
  { ?person wdt:P106 wd:Q15920988 } UNION { ?person wdt:P106 wd:Q17075793 }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?personLabel

SELECT ?state ?stateLabel WHERE {
  ?state wdt:P31 wd:Q35657 .
  ?state wdt:P17 wd:Q30 .
  FILTER(CONTAINS(LCASE(?stateLabel), "a"))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}

SELECT ?person ?personLabel ?birthplaceLabel ?genderLabel WHERE {
  ?person wdt:P31 wd:Q5 .
  ?person wdt:P9252 ?id .
  OPTIONAL { ?person wdt:P19 ?birthplace . }
  OPTIONAL { ?person wdt:P21 ?gender . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?personLabel

SELECT ?satellite ?satelliteLabel ?launchDate WHERE {
  ?satellite wdt:P31 wd:Q170494 ;
             wdt:P619 ?launchDate .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?launchDate

SELECT ?hillfort ?hillfortLabel ?protectionStatusLabel ?coord WHERE {
  ?hillfort wdt:P31 wd:Q105099 .
  OPTIONAL { ?hillfort wdt:P1435 ?protectionStatus . }
  OPTIONAL { ?hillfort wdt:P625 ?coord . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?viaduct ?viaductLabel ?designation ?designationLabel WHERE {
  ?viaduct wdt:P31 wd:Q150784 ;          # instance of viaduct
           wdt:P17 wd:Q145 ;             # located in United Kingdom
           wdt:P1435 ?designation .      # has heritage designation
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?viaductLabel

SELECT ?person ?personLabel WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P166 wd:Q1755990 .
  ?person p:P166 ?awardStatement .
  ?awardStatement ps:P166 wd:Q1755990 ;
                  pq:P585 "2016-01-01T00:00:00Z"^^xsd:dateTime .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

