               wdt:P176 wd:Q286100 .  # manufacturer ARP Instruments, Inc.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?library ?libraryLabel ?coords WHERE {
  ?library wdt:P31 wd:Q7075 ;  # instance of library
           wdt:P17 wd:Q40 .    # country Austria
  OPTIONAL { ?library wdt:P625 ?coords . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT DISTINCT ?place ?placeLabel WHERE {
  ?person wdt:P31 wd:Q5 .
  ?person wdt:P735 wd:Q1249058 .
  ?person wdt:P19 ?place .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?cat ?catLabel WHERE {
  ?cat wdt:P31 wd:Q146 .
  ?cat wdt:P39 wd:Q1072881 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P1433 wd:Q42308166 .
  FILTER NOT EXISTS { ?item wdt:P304 ?page }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?work ?workLabel ?authorLabel ?sitelinks WHERE {
  ?work wdt:P31/wdt:P279* wd:Q7725634 ;
        wdt:P407 wd:Q188 ;
        wikibase:sitelinks ?sitelinks .
  OPTIONAL { ?work wdt:P50 ?author . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?sitelinks)
LIMIT 20

SELECT ?heatwave ?heatwaveLabel ?startDate ?endDate WHERE {
  ?heatwave wdt:P31 wd:Q182707 .
  OPTIONAL { ?heatwave wdt:P580 ?startDate . }
  OPTIONAL { ?heatwave wdt:P582 ?endDate . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?startDate)
LIMIT 20

SELECT ?country ?countryLabel (GROUP_CONCAT(DISTINCT ?languageLabel; SEPARATOR=", ") AS ?languages) WHERE {
  ?country wdt:P31 wd:Q3624078 ; # instance of sovereign state
           wdt:P37 ?language .   # official language
  {
    SELECT ?country (COUNT(DISTINCT ?language) AS ?langCount) WHERE {
      ?country wdt:P31 wd:Q3624078 ;
               wdt:P37 ?language .
    }
    GROUP BY ?country
    HAVING(?langCount >= 2)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?country ?countryLabel
ORDER BY ?countryLabel

SELECT ?building ?buildingLabel WHERE {
  ?building wdt:P31 wd:Q41176 .  # instance of (P31) building (Q41176)
  ?building wdt:P17 wd:Q213 .    # country (P17) Czech Republic (Q213)
  ?building wdt:P31/wdt:P279* wd:Q16970 .  # subclass of place of worship (Q16970)
  ?building wdt:P31/wdt:P279* wd:Q105543609 .  # subclass of fire station (Q105543609)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

