  ?president wdt:P31 wd:Q5 ;
             wdt:P39 wd:Q936870 ;
             wdt:P109 ?signature .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?megalith ?megalithLabel ?coords WHERE {
  ?megalith wdt:P31 wd:Q174682 ;   # instance of megalith
            wdt:P131 wd:Q81949 ;   # located in Basque Country
            wdt:P625 ?coords .     # coordinate location
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?spacecraft ?spacecraftLabel ?inspiration ?inspirationLabel WHERE {
  ?spacecraft wdt:P31 wd:Q40218 .
  OPTIONAL { ?spacecraft wdt:P941 ?inspiration . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?property ?propertyLabel ?coordinates WHERE {
  ?property wdt:P31 wd:Q5 . # Instance of human (placeholder, adjust as needed)
  ?property wdt:P17 wd:Q145 . # Country: United Kingdom
  ?property wdt:P463 wd:Q333515 . # Member of: National Trust
  ?property wdt:P625 ?coordinates . # Coordinate location
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?car ?carLabel ?length WHERE {
  ?car wdt:P31 wd:Q1420 .
  ?car wdt:P2043 ?length .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?length)
LIMIT 50

SELECT ?painting ?paintingLabel ?image WHERE {
  ?painting wdt:P31 wd:Q3305213 ;
            wdt:P2048 ?height ;
            wdt:P2049 ?width ;
            wdt:P18 ?image .
  FILTER(?height > ?width)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?senator ?senatorLabel ?hometown ?hometownLabel WHERE {
  ?senator wdt:P39 wd:Q4416090 ;  # position held: United States senator
           wdt:P551 ?hometown .   # residence (hometown)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?settlement ?settlementLabel WHERE {
  ?settlement wdt:P31 wd:Q486972 ; # instance of human settlement
    wdt:P131 wd:Q81949 . # located in the administrative territorial entity of Basque Country
  ?settlement wdt:P361 ?way . # part of some way
  ?way wdt:P31 wd:Q134159 . # instance of Way of Saint James
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?county1 ?county1Label ?county2 ?county2Label WHERE {
  ?county1 wdt:P31 wd:Q28575 ;  # instance of county
           wdt:P17 ?country1 .   # country
  ?county2 wdt:P31 wd:Q28575 ;
           wdt:P17 ?country2 .
  FILTER(?country1 IN (wd:Q145, wd:Q25, wd:Q22))  # England, Wales, Scotland
  FILTER(?country2 IN (wd:Q145, wd:Q25, wd:Q22))
  FILTER(?county1 != ?county2)
  ?county1 wdt:P47 ?county2 .   # shares border with
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?county1Label ?county2Label

SELECT ?person ?personLabel ?dateOfDeath ?work ?workLabel WHERE {
  ?person wdt:P27 wd:Q668 ;
          wdt:P31 wd:Q5 ;
          wdt:P569 ?dateOfBirth ;
          wdt:P570 ?dateOfDeath .
  FILTER(YEAR(?dateOfDeath) = 1959)
  ?work wdt:P50 ?person .
  FILTER(?dateOfDeath + INTERVAL 60 YEAR <= "2025-01-01"^^xsd:dateTime)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?human ?humanLabel WHERE {
  ?human wdt:P31 wd:Q5.
  FILTER NOT EXISTS { ?human wdt:P40 ?child. }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT DISTINCT ?river ?riverLabel WHERE {
  ?river wdt:P31 wd:Q4022 ;
         wdt:P30 wd:Q51 .

SELECT ?library ?libraryLabel ?coord ?image ?website WHERE {
  ?library wdt:P31 wd:Q7075 ;   # instance of library
           wdt:P17 wd:Q40 ;     # country Austria
           wdt:P625 ?coord .     # coordinate location
  OPTIONAL { ?library wdt:P18 ?image . }
  OPTIONAL { ?library wdt:P856 ?website . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?politician ?politicianLabel WHERE {
  ?politician wdt:P106 wd:Q82955 ;
              wdt:P509 wd:Q12078 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

