  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?sitelinksCount)
LIMIT 10

SELECT ?person ?personLabel ?deathDate WHERE {
  ?person wdt:P106 wd:Q483501 ;
          wdt:P27 wd:Q31 ;
          wdt:P570 ?deathDate .
  FILTER(YEAR(?deathDate) = 1949)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?school ?schoolLabel ?enrollment WHERE {
  ?school wdt:P31 wd:Q3918 . # instance of school
  ?school wdt:P2196 ?enrollment . # student enrollment
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}
