LIMIT 10

SELECT DISTINCT ?country ?countryLabel WHERE {
  # Top 3 traditional universities in Ghana: University of Ghana, Kwame Nkrumah University of Science and Technology, University of Cape Coast
  VALUES ?university { wd:Q1049096 wd:Q1799601 wd:Q2302206 }
  ?person wdt:P69 ?university .
  ?person wdt:P27 ?country .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT DISTINCT ?town ?townLabel WHERE {
  ?street wdt:P31 wd:Q79007 ;      # instance of street
          wdt:P131 wd:Q90 ;        # located in Paris
          wdt:P138 ?town .         # named after the town
  ?town wdt:P17 wd:Q142 .         # country France (ensures French towns)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?state ?stateLabel ?coords ?iNaturalistLink WHERE {
  ?state wdt:P31 wd:Q1221156;   # German state
         wdt:P625 ?coords;
         wdt:P4094 ?placeId.    # iNaturalist place ID
  BIND(CONCAT("https://www.inaturalist.org/observations?place_id=", STR(?placeId)) AS ?iNaturalistLink)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?peak ?peakLabel ?elevation WHERE {
  ?peak wdt:P31 wd:Q207326 ;        # mountain peak
        wdt:P4552 wd:Q123 ;         # mountain range = Alps
        wdt:P2044 ?elevation .      # elevation
  FILTER(?elevation > 1500)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?elevation)

SELECT ?artwork ?artworkLabel ?location ?locationLabel ?coordinates WHERE {
  ?artwork wdt:P170 wd:Q5593 .
  OPTIONAL { ?artwork wdt:P276 ?location . }
  OPTIONAL { ?location wdt:P625 ?coordinates . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?statement ?statementLabel ?property ?value WHERE {
  wd:Q11173 p:P356 [ ps:P356 "10.10.21/JA01577A030" ] .
  ?subject ?p ?statement .
  ?statement ?ps ?value .
  ?property wikibase:directClaim ?ps .
  FILTER(?p = wdt:P31 || ?p = wdt:P2860 || ?p = wdt:P921 || ?p = wdt:P361)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?noun ?nounLabel WHERE {
  ?noun wdt:P31 wd:Q1084 ;   # instance of noun
         wdt:P5185 ?gender .  # grammatical gender
  FILTER(?gender IN (wd:Q499327, wd:Q1775415))  # masculine and feminine
  SERVICE wikibase:label { bd:serviceParam wikibase:language "he,en" }
}

SELECT ?person ?personLabel ?image WHERE {
  ?person wdt:P166 wd:Q1389900 .
  OPTIONAL { ?person wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

