  { ?item wdt:P31 wd:Q34770. } UNION { ?item wdt:P31 wd:Q33384. }
  ?item wdt:P18 ?image.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?itemLabel

SELECT ?parishLabel ?countyLabel ?coord WHERE {
  ?parish wdt:P31 wd:Q7134970 ;        # instance of parish of New South Wales
          wdt:P131 ?county .           # located in county
  ?county wdt:P31 wd:Q3331125 ;        # instance of county of New South Wales
          wdt:P131 wd:Q3224 .          # located in New South Wales
  OPTIONAL { ?parish wdt:P625 ?coord . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
