  ?org wdt:P31 wd:Q43229 ;  # instance of organization
       wdt:P276 ?location . # location
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT DISTINCT ?watercraft ?watercraftLabel WHERE {
  ?watercraft wdt:P31/wdt:P279* wd:Q1229765 ;  # instance or subclass of watercraft
              wdt:P17 wd:Q142 .                # country France
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
