SELECT ?year (COUNT(DISTINCT ?member) AS ?switched) WHERE {
  ?member wdt:P39 wd:Q16707842 . # Member of the UK Parliament
  ?member p:P39 ?positionStmt .
  ?positionStmt ps:P39 wd:Q16707842 ;
              pq:P580 ?startTime ;
              pq:P582 ?endTime .
  ?member p:P39 ?otherPositionStmt .
  ?otherPositionStmt ps:P39 wd:Q16707842 ;
                     pq:P580 ?otherStartTime ;
                     pq:P582 ?otherEndTime .
  FILTER(?startTime < ?otherStartTime)
  BIND(YEAR(?otherStartTime) AS ?year)
  FILTER(?year >= 1830 && ?year <= 1910)
}
GROUP BY ?year
ORDER BY ?year

