      OPTIONAL { ?pathway wdt:P527 ?gene . } # has part (gene)
      OPTIONAL { ?pathway wdt:P527 ?metabolite . } # has part (metabolite)
      FILTER NOT EXISTS { ?gene wdt:P31 wd:Q7187 . } # exclude if gene is not a gene
      FILTER NOT EXISTS { ?metabolite wdt:P31 wd:Q11173 . } # exclude if metabolite is not a metabolite
    }
    GROUP BY ?pathway
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT DISTINCT ?author ?authorLabel ?work ?workLabel ?publicationDate WHERE {
  ?author wdt:P106 wd:Q482980 ; # author
          wdt:P31 wd:Q5 .       # human
  ?work wdt:P50 ?author ;       # authored by
        wdt:P953 [] ;           # available online at URL
        wdt:P577 ?publicationDate .
  FILTER(YEAR(?publicationDate) >= 1500 && YEAR(?publicationDate) <= 1800)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?authorLabel

