SELECT ?continent ?continentLabel ?river ?riverLabel ?length WHERE {
  # Define continents
  VALUES ?continent { wd:Q49 wd:Q51 wd:Q48 wd:Q46 wd:Q50 wd:Q52 wd:Q47 } # North America, South America, Europe, Africa, Asia, Australia, Antarctica
  ?continent wdt:P31 wd:Q5107 . # instance of continent

  # Find rivers on each continent
  ?river wdt:P31 wd:Q4022 ; # instance of river
         wdt:P17 ?country . # located in country
  ?country wdt:P30 ?continent . # continent of country
  ?river wdt:P2043 ?length . # length in meters

  # Get the longest river per continent
  {
    SELECT ?continent (MAX(?length) AS ?maxLength) WHERE {
      ?river wdt:P31 wd:Q4022 ;
             wdt:P17 ?country .
      ?country wdt:P30 ?continent .
      ?river wdt:P2043 ?length .
    }
    GROUP BY ?continent
  }
  FILTER(?length = ?maxLength)

  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY ?continentLabel

