  BIND(wikibase:sitelinks(?city) AS ?city_sitelinks)
  BIND(wikibase:sitelinks(?country) AS ?country_sitelinks)
  FILTER(?city_sitelinks > ?country_sitelinks)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?city_sitelinks)

