SELECT ?award ?awardLabel ?totalRecipients ?femaleRecipients ?percentage WHERE {
  {
    SELECT ?award (COUNT(DISTINCT ?recipient) AS ?totalRecipients) (COUNT(DISTINCT ?femaleRecipient) AS ?femaleRecipients) WHERE {
      ?award wdt:P31 wd:Q618779 . # instance of award
      ?recipient wdt:P166 ?award . # recipient of award
      OPTIONAL {
        ?femaleRecipient wdt:P166 ?award ;
                         wdt:P21 wd:Q6581072 . # female gender
      }
    }
    GROUP BY ?award
    HAVING (?totalRecipients > 0)
  }
  BIND ((?femaleRecipients * 100.0) / ?totalRecipients AS ?percentage)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?percentage)

