PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
SELECT ((?femaleCount * 100.0) / ?totalCount AS ?percentage) WHERE {
  {
    SELECT (COUNT(DISTINCT ?person) AS ?totalCount) WHERE {
      ?person wdt:P166 wd:Q7191;
              wdt:P31 wd:Q5.
    }
  }
  {
    SELECT (COUNT(DISTINCT ?woman) AS ?femaleCount) WHERE {
      ?woman wdt:P166 wd:Q7191;
             wdt:P31 wd:Q5;
             wdt:P21 wd:Q6581072.
    }
  }
}

SELECT ?controversy ?controversyLabel ?nolang ?article ?langCount WHERE {
  ?controversy wdt:P31 wd:Q1515293 .
  ?article schema:about ?controversy ;
            schema:isPartOf <https://en.wikipedia.org/> ;
            wikibase:statements ?nolang .
  BIND( IRI(REPLACE(STR(?article), "https://en.wikipedia.org/wiki/", "https://en.wikipedia.org/w/index.php?title=")) AS ?articleUrl )
  {
    SELECT ?controversy (COUNT(DISTINCT ?langArticle) AS ?langCount) WHERE {
      ?langArticle schema:about ?controversy .
      ?langArticle schema:isPartOf ?wiki .
      FILTER(CONTAINS(STR(?wiki), "wikipedia.org"))
    }
    GROUP BY ?controversy
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY DESC(?langCount)

