SELECT ?station ?stationLabel ?previousStation ?previousStationLabel ?nextStation ?nextStationLabel WHERE {
  # Find the railway station for Dibrugarh
  wd:Q1207001 wdt:P31 wd:Q55488 ; # Dibrugarh railway station
              wdt:P197 ?nextStation .
  # Find the railway station for Scottish Highlands (assuming Inverness as a major station)
  wd:Q1001480 wdt:P31 wd:Q55488 ; # Inverness railway station
              wdt:P197 ?previousStation .
  # Find stations on the same line between them
  ?station wdt:P31 wd:Q55488 ;
           wdt:P197 ?nextStation ;
           wdt:P197 ?previousStation .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
LIMIT 10

