  } UNION {
    ?work wdt:P195 wd:Q636400 . # Ashmolean Museum
  }
  ?work wdt:P180 ?subject .
}
GROUP BY ?subject ?subjectLabel
ORDER BY DESC(?count)
LIMIT 20

SELECT ?language ?languageLabel (COUNT(?album) AS ?count) WHERE {
  ?album wdt:P31 wd:Q482994 ;  # instance of music album
         wdt:P407 ?language .   # language of work or name
