  FILTER(?account1 != ?account2)
  FILTER(LCASE(?account1) = LCASE(?account2))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT (SUBSTR(?softwareLabel, 1, 1) AS ?firstLetter) WHERE {
  ?software wdt:P31 wd:Q341.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?firstLetter

SELECT ?country ?countryLabel (COUNT(?demonstration) AS ?numberOfDemonstrations) WHERE {
  ?demonstration wdt:P31 wd:Q175331 ;  # instance of demonstration
                 wdt:P17 ?country .    # country
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?country ?countryLabel
ORDER BY DESC(?numberOfDemonstrations)

SELECT ?museum ?museumLabel ?image ?distance WHERE {
  wd:Q177607 wdt:P625 ?cesisLoc .
  ?museum wdt:P31 wd:Q33506 ;
          wdt:P625 ?museumLoc .
  BIND(geof:distance(?cesisLoc, ?museumLoc) AS ?distance)
  FILTER(?distance < 50000)
  OPTIONAL { ?museum wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?distance

SELECT ?artist ?artistLabel ?deathDate ?causeLabel ?image WHERE {
  ?artist wdt:P106 wd:Q483501 ;            # occupation: artist
          wdt:P509 ?cause .                # cause of death
  FILTER(?cause IN (wd:Q158340, wd:Q18074576))  # death in Nazi concentration camps
  OPTIONAL { ?artist wdt:P570 ?deathDate . }
  OPTIONAL { ?artist wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?artistLabel

SELECT ?database ?databaseLabel ?idCount WHERE {
  ?database wdt:P31 wd:Q8513 .  # instance of database
  ?database wdt:P1893 ?sparqlEndpoint .  # has SPARQL endpoint
  {
    SELECT ?database (COUNT(?id) AS ?idCount) WHERE {
      ?id wdt:P31 wd:Q5 .  # any item that is a human
      ?id ?property ?database .  # property pointing to database
      FILTER(STRSTARTS(STR(?property), "http://www.wikidata.org/entity/P"))
    }
    GROUP BY ?database
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY DESC(?idCount)

SELECT (COUNT(DISTINCT ?word) AS ?count) WHERE {
  ?word wdt:P31 wd:Q8171 ;  # instance of word
         wdt:P5186 ?dictionary .  # part of dictionary
  ?dictionary wdt:P31 wd:Q33742 .  # instance of dictionary
  FILTER NOT EXISTS {
    ?word wdt:P5186 ?otherDictionary .
    FILTER(?otherDictionary != ?dictionary)
  }
}

SELECT ?software ?softwareLabel ?field ?fieldLabel WHERE {
  ?software wdt:P31 wd:Q107649214.          # instance of research software
  ?software wdt:P275 ?license.               # has a license
  ?license wdt:P31 wd:Q1130645.              # license is an open-source license
  ?software wdt:P101 ?field.                 # field of work
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?

SELECT ?person ?personLabel ?pageCount WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P570 ?deathDate .
  FILTER(YEAR(?deathDate) = 2018)
  {
    SELECT ?person (COUNT(DISTINCT ?page) AS ?pageCount) WHERE {
      ?page schema:about ?person ;
            schema:isPartOf <https://en.wikipedia.org/> .
    }
    GROUP BY ?person
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY DESC(?pageCount)

SELECT DISTINCT ?person ?personLabel ?dateBirth ?headOfGovLabel ?image WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P19 wd:Q25 ;     # born in Wales (Q25)
          wdt:P569 ?dateBirth ;
          wdt:P1317 ?headOfGov . # held position of head of government
  OPTIONAL { ?person wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?personLabel

SELECT ?church ?churchLabel ?property ?propertyLabel ?saint ?saintLabel WHERE {
  ?church wdt:P31 wd:Q16970 .  # instance of church
  ?church ?property ?saint .
  ?saint wdt:P31 wd:Q5 .       # instance of human (saint)
