  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?river ?riverLabel (MAX(?length) AS ?maxLength) WHERE {
  ?river wdt:P31 wd:Q4022 ;         # instance of river
         wdt:P17 wd:Q142 ;          # country France
         wdt:P2043 ?length .        # length in meters
  FILTER NOT EXISTS {
    ?department wdt:P31 wd:Q6465 ;  # department of France
                wdt:P138 ?river .   # named after this river
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?river ?riverLabel
ORDER BY DESC(?maxLength)

SELECT ?pathway ?pathwayLabel ?protein ?proteinLabel ?pdbId WHERE {
  ?pathway wdt:P31 wd:Q4915012.   # instance of biological pathway
  ?pathway wdt:P527 ?protein.     # protein component of the pathway
  ?protein wdt:P638 ?pdbId.       # PDB structure identifier
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
