  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". ?property rdfs:label ?propertyLabel. }
}
GROUP BY ?property ?propertyLabel
ORDER BY DESC(?frequency)

SELECT ?scene ?sceneLabel WHERE {
