              wdt:P1082 ?population . # has population
  FILTER NOT EXISTS { ?subdivision wdt:P194 ?legislature . } # no legislative body
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
