GROUP BY ?propertyType ?propertyTypeLabel
ORDER BY DESC(?frequency)

SELECT ?song ?songLabel WHERE {
  ?song wdt:P31 wd:Q7366 ;          # instance of song
        wdt:P1476 ?title .          # title
  ?name wdt:P31 wd:Q11879590 ;      # instance of female given name
        wdt:P1705 ?nameString .     # native label
  FILTER(LCASE(?title) = LCASE(?nameString))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
