SELECT ?mathematician ?mathematicianLabel ?birthYear WHERE {
  ?mathematician wdt:P106 wd:Q170790 ;
                 wdt:P569 ?birthDate .
  BIND(YEAR(?birthDate) AS ?birthYear)
  FILTER(?birthYear > 1)
  FILTER NOT EXISTS {
    ?divisor wdt:P31 wd:Q5 .
    FILTER(?divisor > 1 && ?divisor < ?birthYear && ?birthYear MOD ?divisor = 0)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

