SELECT ?century ?centuryLabel (GROUP_CONCAT(DISTINCT ?personLabel; SEPARATOR=", ") AS ?people) WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P172 wd:Q47503 ;
          wdt:P569 ?birthDate ;
          wdt:P570 ?deathDate .
  OPTIONAL { ?person wdt:P19 ?birthPlace . }
  FILTER(BOUND(?birthPlace))
  BIND(IF(YEAR(?deathDate) >= 1001 && YEAR(?deathDate) <= 1100, "11th century",
          IF(YEAR(?deathDate) >= 1101 && YEAR(?deathDate) <= 1200, "12th century",
          IF(YEAR(?deathDate) >= 1201 && YEAR(?deathDate) <= 1300, "13th century",
          IF(YEAR(?deathDate) >= 1301 && YEAR(?deathDate) <= 1400, "14th century",
          IF(YEAR(?deathDate) >= 1401 && YEAR(?deathDate) <= 1500, "15th century",
          IF(YEAR(?deathDate) >= 1501 && YEAR(?deathDate) <= 1600, "16th century",
          IF(YEAR(?deathDate) >= 1601 && YEAR(?deathDate) <= 1700, "17th century",
          IF(YEAR(?deathDate) >= 1701 && YEAR(?deathDate) <= 1800, "18th century",
          IF(YEAR(?deathDate) >= 1801 && YEAR(?deathDate) <= 1900, "19th century",
          IF(YEAR(?deathDate) >= 1901 && YEAR(?deathDate) <= 2000, "20th century",
          IF(YEAR(?deathDate) >= 2001 && YEAR(?deathDate) <= 2100, "21st century", "Other"))))))))))) AS ?century)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?century ?centuryLabel
ORDER BY ?century

SELECT ?company ?companyLabel ?revenue WHERE {
