SELECT ?occupation ?occupationLabel ?maleCount ?femaleCount (ABS(?maleCount - ?femaleCount) AS ?imbalance) WHERE {
  {
    SELECT ?occupation (COUNT(?male) AS ?maleCount) WHERE {
      ?male wdt:P21 wd:Q6581097 ;   # male
             wdt:P106 ?occupation ;  # occupation
             wdt:P569 ?birthDate .   # birth date
      FILTER(YEAR(?birthDate) >= 1980 && YEAR(?birthDate) <= 2000)  # approximate US working age
    }
    GROUP BY ?occupation
  }
  {
    SELECT ?occupation (COUNT(?female) AS ?femaleCount) WHERE {
      ?female wdt:P21 wd:Q6581072 ; # female
             wdt:P106 ?occupation ;
             wdt:P569 ?birthDate .
      FILTER(YEAR(?birthDate) >= 1980 && YEAR(?birthDate) <= 2000)
    }
    GROUP BY ?occupation
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY DESC(?imbalance)
LIMIT 20

