        wdt:P9327 [] .                  # has UK Lakes Portal ID
}

SELECT DISTINCT ?person ?personLabel ?otherPerson ?otherPersonLabel WHERE {
  ?person wdt:P40 ?otherPerson .
  { ?otherPerson wdt:P22 ?person } UNION { ?otherPerson wdt:P25 ?person }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT DISTINCT ?country ?countryLabel ?officialLanguage ?officialLanguageLabel WHERE {
