SELECT ?person ?personLabel ?birthDate ?image ?age WHERE {
  ?person wdt:P21 wd:Q6581072 .           # female
  ?person wdt:P106 wd:Q33999 .           # actress
  ?person wdt:P569 ?birthDate .          # date of birth
  BIND((YEAR(NOW()) - YEAR(?birthDate)) AS ?age)
  FILTER(?age < 70)
  FILTER NOT EXISTS { ?person wdt:P570 ?deathDate . }  # alive
  wd:Q221680 wdt:P40+ ?person .         # descendant of first king of Navarre
  OPTIONAL { ?person wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?personLabel

SELECT ?saint ?saintLabel ?feastDay ?month ?day WHERE {
  ?saint wdt:P31 wd:Q5 ;          # instance of human
