  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
  FILTER(STRSTARTS(STR(?coordinates), "Point("))
}

SELECT ?language ?languageLabel (COUNT(DISTINCT ?lexeme) AS ?count) WHERE {
  # Only consider lexical entries
  ?lexeme a ontolex:LexicalEntry ;
          wdt:P31 wd:Q1511471 ;                     # instance of lexeme
          wdt:P5189 ?language ;                     # language of the lexeme
          wdt:P5188 [] ;                            # must have a lexical category
          wdt:P598 [] .                             # must have a lemma

  # Exclude lexemes that have senses
  FILTER NOT EXISTS { ?lexeme wdt:P5137 ?sense }

  # Exclude lexemes that have any other direct statements outside the mandatory ones
  FILTER NOT EXISTS {
    ?lexeme ?p ?o .
    FILTER(STRSTARTS(STR(?p), "http://www.wikidata.org/prop/direct/") &&
           STR(?p) NOT IN("http://www.wikidata.org/prop/direct/P31",
                         "http://www.wikidata.org/prop/direct/P5189",
                         "http://www.wikidata.org/prop/direct/P5188",
                         "http://www.wikidata.org/prop/direct/P598"))
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}
GROUP BY ?language ?languageLabel
HAVING (COUNT(?lexeme) < 10)
ORDER BY DESC(?count)

SELECT ?institution ?institutionLabel WHERE {
  # Identify the vBIB conference series by label (case-insensitive)
  ?series wdt:P31 wd:Q472927 ;           # instance of conference series
          rdfs:label ?label .
  FILTER(CONTAINS(LCASE(?label), "vbib"))

  # Institution should be an organization (optional but aligns with "institution")
  ?institution wdt:P31/wdt:P279* wd:Q43229 .

  # Ensure the institution contributed to every vBIB conference
  NOT EXISTS {
    ?conf wdt:P31 ?series .
    FILTER NOT EXISTS { ?conf wdt:P710 ?institution . }   # participant property
  }

  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

