             wdt:P39 wd:Q11696 .            # position held: President of the United States
  ?president p:P39 ?positionStatement .
  ?positionStatement ps:P39 wd:Q11696 ;      # statement for that position
                          pq:P580 ?startDate .  # start time
  OPTIONAL { ?president wdt:P569 ?birthDate . }
