SELECT ?church1 ?church1Label ?church2 ?church2Label ?distance WHERE {
  ?church1 wdt:P31 wd:Q16970 ; # instance of church
           wdt:P17 wd:Q145 ;   # country United Kingdom
           wdt:P625 ?coord1 .   # coordinate location
  ?church2 wdt:P31 wd:Q16970 ;
           wdt:P17 wd:Q145 ;
           wdt:P625 ?coord2 .
  FILTER (?church1 != ?church2)
  BIND (geof:distance(?coord1, ?coord2) AS ?distance)
  FILTER (?distance > 0 && ?distance <= 0.1) # within 0.1 degrees (approx 11 km)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY ?distance

