SELECT ?winner ?winnerLabel ?nationalityLabel ?stage ?stageLabel ?year WHERE {
  ?stage wdt:P31 wd:Q12138 .              # instance of Tour de France stage
  ?stage wdt:P585 ?date .                  # point in time
  ?stage wdt:P1923 ?winner .               # winner
  ?winner wdt:P27 ?nationality .           # country of citizenship
  BIND(YEAR(?date) AS ?year)
  FILTER(?year >= 1903 && ?year <= 2022)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
