SELECT DISTINCT ?company ?companyLabel ?founder ?founderLabel ?founderBirthPlace ?founderBirthPlaceLabel WHERE {
  ?company wdt:P31 wd:Q4830453 .          # instance of business enterprise
  ?company wdt:P17 wd:Q30 .              # country = United States
  ?company wdt:P112 ?founder .           # founded by
  ?founder wdt:P569 ?birthDate .         # birth date
  ?founder wdt:P19 ?founderBirthPlace .  # place of birth
  FILTER NOT EXISTS { ?founderBirthPlace wdt:P17 wd:Q30 }  # birth place not in US
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
UNION
{
  ?company wdt:P31 wd:Q4830453 .
  ?company wdt:P17 wd:Q30 .
  ?company wdt:P112 ?parent .            # founder is a parent
  ?parent wdt:P40 ?founder .             # child of parent
  ?founder wdt:P569 ?birthDate .
  ?founder wdt:P19 ?founderBirthPlace .
  FILTER NOT EXISTS { ?founderBirthPlace wdt:P17 wd:Q30 }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY ?companyLabel

