PREFIX wd: <http://www.wikidata.org/entity/>
PREFIX wdt: <http://www.wikidata.org/prop/direct/>
PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX bd: <http://www.bigdata.com/rdf#>

SELECT ?eventLabel ?date ?locationLabel ?image WHERE {
  {
    wd:Q9092 wdt:P569 ?date .
    BIND("Birth" AS ?eventLabel)
    OPTIONAL { wd:Q9092 wdt:P19 ?location . }
    OPTIONAL { wd:Q9092 wdt:P18 ?image . }
  } UNION {
    wd:Q9092 wdt:P570 ?date .
    BIND("Death" AS ?eventLabel)
    OPTIONAL { wd:Q9092 wdt:P20 ?location . }
    OPTIONAL { wd:Q9092 wdt:P18 ?image . }
  } UNION {
    wd:Q9092 wdt:P793 ?event .
    ?event rdfs:label ?eventLabel .
    FILTER(LANG(?eventLabel) = "en")
    OPTIONAL { ?event wdt:P585 ?date . }
    OPTIONAL { ?event wdt:P276 ?location . }
    OPTIONAL { ?event wdt:P18 ?image . }
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?date

SELECT ?artwork ?artworkLabel ?title ?rhymePattern WHERE {
  ?artwork wdt:P31 wd:Q838948 ;  # instance of artwork
           wdt:P1476 ?title .   # title
  BIND(STR(?title) AS ?titleStr)
  # Check if the title ends with a common rhyming pattern (e.g., "ing", "tion", "ity")
  FILTER(REGEX(?titleStr, "(ing|tion|ity|ness|ment|able|ible|ous|ful|less|ly|ed|en|er|est|y|ie|ey|ow|aw|ay|oy|uy|ee|oo|oa|ai|ei|ie|ou|au|eu|iu|oi|ui|ey|ay|oy|uy|ee|oo|oa|ai|ei|ie|ou|au|eu|iu|oi|ui)$"))
  BIND(REPLACE(?titleStr, ".*(ing|tion|ity|ness|ment|able|ible|ous|ful|less|ly|ed|en|er|est|y|ie|ey|ow|aw|ay|oy|uy|ee|oo|oa|ai|ei|ie|ou|au|eu|iu|oi|ui|ey|ay|oy|uy|ee|oo|oa|ai|ei|ie|ou|au|eu|iu|oi|ui)$", "$1") AS ?rhymePattern)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?composer ?composerLabel (COUNT(?film) AS ?filmCount) WHERE {
  ?film wdt:P31 wd:Q11424 ;   # instance of film
        wdt:P86 ?composer .    # composer of film
  ?composer wdt:P106 wd:Q1064835 .  # occupation: film score composer
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?composer ?composerLabel
HAVING (COUNT(?film) > 100)
ORDER BY DESC(?filmCount)

SELECT DISTINCT ?person ?personLabel ?ancestor ?ancestorLabel ?typeLabel WHERE {
  VALUES ?position { wd:Q15964890 wd:Q16707842 wd:Q25290 }
  ?person wdt:P39 ?position .
  ?person (wdt:P22|wdt:P25){1,5} ?ancestor .
  ?ancestor wdt:P31 ?type .
  VALUES ?type { wd:Q267378 wd:Q156326 wd:Q95074 wd:Q190182 }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?personLabel

SELECT DISTINCT ?property ?propertyLabel WHERE {
  { ?preprint wdt:P31 wd:Q580922 ; ?property ?article . ?article wdt:P31 wd:Q191067 . }
  UNION
  { ?article wdt:P31 wd:Q191067 ; ?property ?preprint . ?preprint wdt:P31 wd:Q580922 . }
  FILTER(STRSTARTS(STR(?property), "http://www.wikidata.org/prop/direct/"))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
LIMIT 100

SELECT ?institution ?institutionLabel (COUNT(DISTINCT ?senator) AS ?count) WHERE {
  ?senator wdt:P39 wd:Q4416090 .  # position held = United States senator
  ?senator wdt:P69 ?institution .  # educated at
