SELECT DISTINCT ?person ?personLabel ?university ?universityLabel WHERE {
  ?person p:P39 ?posStatement .
  ?posStatement ps:P39 wd:Q483501 .  # position held: ambassador
  ?posStatement pq:P1416 wd:Q145 .    # applies to jurisdiction: United Kingdom
  ?person wdt:P69 ?university .        # educated at a university
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY ?personLabel

SELECT ?lighthouse ?lighthouseLabel ?coordinates WHERE {
  ?lighthouse wdt:P31 wd:Q39715 ;  # instance of lighthouse
              wdt:P17 ?country .   # country
  ?country wdt:P30 wd:Q18 .        # continent South America
  OPTIONAL { ?lighthouse wdt:P625 ?coordinates . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

PREFIX wikibase: <http://wikiba.se/ontology#>
PREFIX dct: <http://purl.org/dc/terms/>
PREFIX bd: <http://www.bigdata.com/rdf#>

SELECT DISTINCT ?language ?languageLabel WHERE {
  {
    SELECT DISTINCT ?language WHERE {
      ?lex1 wikibase:lemma ?lemma .
      ?lex1 dct:language ?language .
      ?lex2 wikibase:lemma ?lemma .
      ?lex2 dct:language ?other .
      FILTER(?lex1 != ?lex2 && ?language != ?other)
    }
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?episode ?episodeLabel ?subject ?subjectLabel WHERE {
  ?episode wdt:P31 wd:Q21191270 ;   # instance of episode
           wdt:P179 wd:Q23668 ;     # series: The West Wing
           wdt:P921 ?subject .      # main subject
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?episodeLabel

SELECT DISTINCT ?person ?personLabel ?birthYear ?deathYear ?placeOfBirthLabel ?placeOfDeathLabel WHERE {
  ?person wdt:P31 wd:Q5 .
  OPTIONAL { ?person wdt:P569 ?birthDate . BIND(YEAR(?birthDate) AS ?birthYear) }
  OPTIONAL { ?person wdt:P570 ?deathDate . BIND(YEAR(?deathDate) AS ?deathYear) }
  OPTIONAL { ?person wdt:P19 ?placeOfBirth . }
  OPTIONAL { ?person wdt:P20 ?placeOfDeath . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?personLabel

SELECT ?item ?itemLabel ?location ?coord1 ?coord2 ?distance WHERE {
  ?item wdt:P31 wd:Q13100073 ; # instance of commune of France
        wdt:P625 ?location .   # coordinate location
  ?item wdt:P31 wd:Q13100073 .
  ?otherItem wdt:P31 wd:Q13100073 ;
             wdt:P625 ?otherLocation .
  FILTER (?item != ?otherItem && ?itemLabel = ?otherItemLabel)
  BIND(geof:distance(?location, ?otherLocation) AS ?distance)
  BIND(?location AS ?coord1)
  BIND(?otherLocation AS ?coord2)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?place ?placeLabel ?welsh_spelling WHERE {
  ?place wdt:P31 wd:Q532 . # instances of human settlement
  OPTIONAL { ?place wdt:P1814 ?welsh_spelling }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en,cy" }
}

SELECT ?property ?propertyLabel (COUNT(?item) AS ?count) WHERE {
  ?item wdt:P31 wd:Q4006 .
  ?item ?property ?value .
  FILTER(STRSTARTS(STR(?property), "http://www.wikidata.org/prop/direct/"))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?property ?propertyLabel
ORDER BY DESC(?count)
LIMIT 20

SELECT ?museum ?museumLabel ?location ?distance WHERE {
  SERVICE wikibase:around {
    ?museum wdt:P31 wd:Q33506;
            wdt:P625 ?location.
    bd:serviceParam wikibase:center "Point(0 0)"^^geo:wktLiteral; # Replace with your coordinates
                    wikibase:radius "20".
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?person ?personLabel WHERE {
  ?person wdt:P69 wd:Q37126 ;
          wdt:P31 wd:Q5 .
  FILTER NOT EXISTS { ?person wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?place ?placeLabel ?coordinates WHERE {
  ?place wdt:P625 ?coordinates .
  FILTER(geof:distance(?coordinates, "Point(48.87 2.29)"^^geosparql:wktLiteral) < 1.0)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?language ?languageLabel WHERE {
  wd:Q142 wdt:P37 ?language .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?hillfort ?hillfortLabel ?location ?image ?coords WHERE {
  ?hillfort wdt:P31 wd:Q105084 .  # instance of hillfort
  ?hillfort wdt:P17 wd:Q145 .   # country: United Kingdom
  ?hillfort wdt:P276 ?location . # location
  OPTIONAL { ?hillfort wdt:P18 ?image . } # image
  OPTIONAL { ?hillfort wdt:P625 ?coords . } # coordinate location
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?country ?countryLabel (COUNT(DISTINCT ?person) AS ?count) WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P735 ?givenName ;
          wdt:P27 ?country .
  ?givenName rdfs:label ?givenNameLabel .
  FILTER(LANG(?givenNameLabel) = "en" && 
         (STRSTARTS(UCASE(?givenNameLabel), "X") || STRSTARTS(UCASE(?givenNameLabel), "Q")))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?country ?countryLabel
ORDER BY DESC(?count)

SELECT ?woman ?womanLabel ?birthDate WHERE {
  ?woman wdt:P31 wd:Q5;                # instance of human
         wdt:P21 wd:Q6581072;          # gender female
         wdt:P19 wd:Q145.              # place of birth United Kingdom
  OPTIONAL { ?woman wdt:P569 ?birthDate . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?womanLabel

SELECT ?facility ?facilityLabel ?type ?typeLabel ?coord WHERE {
  ?facility wdt:P31/wdt:P279* wd:Q169930 .  # instance/subclass of medical facility
  ?facility wdt:P131 wd:Q1529649 .          # located in Murshidabad district
  ?facility wdt:P625 ?coord .               # coordinate location
  ?facility wdt:P31 ?type .                 # type of facility
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?deathDate ?graveImage WHERE {
  ?person wdt:P31 wd:Q5 .
  ?person wdt:P119 wd:Q384321 .
  ?person wdt:P570 ?deathDate .
  FILTER(YEAR(?deathDate) >= 1800 && YEAR(?deathDate) <= 1849)
  OPTIONAL { ?person wdt:P18 ?graveImage . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?deathDate

SELECT ?person ?personLabel ?birthDate ?image ?positionLabel WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P106 wd:Q82955 ;          # occupation: politician
          wdt:P27 wd:Q38 ;              # country of citizenship: Italy
          wdt:P569 ?birthDate .         # date of birth
  FILTER( (?birthDate >= "1944-01-01"^^xsd:dateTime && ?birthDate <= "1974-12-31"^^xsd:dateTime) )  # age between 50 and 80 as of 2024
  ?person wdt:P39 ?position .           # held position
  ?position wdt:P31 wd:Q16707842 .      # instance of: ministerial position
  OPTIONAL { ?person wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?personLabel

SELECT ?president ?presidentLabel (MIN(?startTime) AS ?firstStart) WHERE {
  ?president p:P39 ?statement .
  ?statement ps:P39 wd:Q11696 .
  ?statement pq:P580 ?startTime .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
GROUP BY ?president ?presidentLabel
ORDER BY ?firstStart

SELECT ?item ?itemLabel ?image WHERE {
  VALUES ?item { wd:Q3172440 wd:Q2868326 }
  OPTIONAL { ?item wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?gender ?genderLabel (COUNT(DISTINCT ?person) AS ?count) WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P21 ?gender ;
          wdt:P166 ?prize .
  ?prize wdt:P31 wd:Q200098 .
  VALUES ?gender { wd:Q6581097 wd:Q6581072 }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?gender ?genderLabel

SELECT ?region ?regionLabel ?percentage ?map WHERE {
  wd:Q25 wdt:P31 wd:Q5 . # Wales is a country
  ?region wdt:P131 wd:Q25 . # Region is part of Wales
  ?region wdt:P1098 ?percentage . # Percentage of Welsh speakers
  OPTIONAL { ?region wdt:P18 ?map . } # Map image
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?language ?languageLabel ?location ?locationLabel WHERE {
  ?language wdt:P31 wd:Q34770 ;  # instance of language
            wdt:P17 ?location .   # country of origin
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?languageLabel

SELECT ?person ?personLabel ?birthDate WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P569 ?birthDate .
  FILTER (MONTH(?birthDate) = 1)
  FILTER (YEAR(?birthDate) % 4 = 0 && (YEAR(?birthDate) % 100 != 0 || YEAR(?birthDate) % 400 = 0))
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY ?birthDate

SELECT ?author ?authorLabel ?needItem ?needItemLabel WHERE {
  ?author wdt:P106 wd:Q482980 .
  ?author wdt:P1416 wd:Q1135423 .
  ?author wdt:P2341 ?needItem .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?authorLabel

SELECT DISTINCT ?monarch ?monarchLabel ?placeOfDeathLabel ?dateOfDeath WHERE {
  ?monarch wdt:P39 wd:Q107837 .         # position held: monarch of Denmark
  ?monarch wdt:P570 ?dateOfDeath .      # date of death
  ?monarch wdt:P20 ?placeOfDeath .      # place of death
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?monarchLabel

SELECT ?part ?partLabel WHERE {
  wd:Q288679 wdt:P527 ?part .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT DISTINCT ?poem ?poemLabel ?month WHERE {
  ?poem wdt:P50 wd:Q7241 ;   # author: Rabindranath Tagore
        wdt:P31 wd:Q5185279 ; # instance of: poem
        wdt:P571 ?date .      # inception date
  BIND(MONTH(?date) AS ?month)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?month

SELECT ?restaurant ?restaurantLabel ?location ?image ?michelinStar WHERE {
  ?restaurant wdt:P31 wd:Q11707 ;          # instance of restaurant
              wdt:P17 wd:Q39 ;             # country: Switzerland
              wdt:P625 ?location .         # coordinate location
  OPTIONAL { ?restaurant wdt:P18 ?image . }
  OPTIONAL { ?restaurant wdt:P166 ?michelinStar . }
  FILTER EXISTS { ?restaurant wdt:P166 wd:Q60639 }  # has Michelin star
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?economist ?economistLabel ?birthplaceLabel WHERE {
  ?economist wdt:P106 wd:Q188094 .
  ?economist wdt:P19 ?birthplace .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?person ?personLabel ?dateOfDeath ?image WHERE {
  ?person wdt:P31 wd:Q5 ;
          wdt:P570 ?dateOfDeath .
  FILTER(YEAR(?dateOfDeath) >= 1969 && YEAR(?dateOfDeath) <= 1970)
  OPTIONAL { ?person wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?dateOfDeath

SELECT ?tramLine ?tramLineLabel ?coords WHERE {
  ?tramLine wdt:P31/wdt:P279* wd:Q15284203 .
  ?tramLine wdt:P17 wd:Q142 .
  ?tramLine wdt:P625 ?coords .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?opening ?openingLabel ?sitelinks WHERE {
  ?opening wdt:P31 wd:Q2005526.  # instance of chess opening
  ?opening wikibase:sitelinks ?sitelinks.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?sitelinks)

SELECT ?country ?countryLabel ?painting ?paintingLabel ?image WHERE {
  ?painting wdt:P31 wd:Q3305213 ;  # instance of painting
            wdt:P17 ?country .    # country of origin
  OPTIONAL { ?painting wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" . }
}
GROUP BY ?country ?countryLabel ?painting ?paintingLabel ?image
ORDER BY ?countryLabel

SELECT ?item ?itemLabel WHERE {
  ?item wdt:P31 wd:Q5 .          # instance of human
  ?item wdt:P21 wd:Q6581072 .    # sex or gender: female
  ?item wdt:P27 wd:Q258 .        # country of citizenship: South Africa
  ?item wdt:P31 wd:Q5 .          # ensure it's a human (redundant but safe)
  ?item wdt:P569 ?birth .        # optional: birth date for filtering
  ?item wdt:P18 ?image .         # optional: image
  ?article schema:about ?item .
  ?article schema:isPartOf <https://en.wikipedia.org/> .
  FILTER NOT EXISTS {
    ?wikiquote schema:about ?item .
    ?wikiquote schema:isPartOf <https://en.wikiquote.org/> .
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?place ?placeLabel ?location ?image WHERE {
  SERVICE wikibase:around {
    ?place wdt:P625 ?location .
    bd:serviceParam wikibase:center "Point(13.4050 52.5200)"^^geo:wktLiteral . # Example: Berlin coordinates
    bd:serviceParam wikibase:radius "10" .
    bd:serviceParam wikibase:distance ?distance .
  }
  ?place wdt:P31/wdt:P279* wd:Q294466 . # Public space
  ?place wdt:P527 wd:Q173336 . # Has table tennis table
  OPTIONAL { ?place wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?distance
LIMIT 20

SELECT ?movie ?movieLabel ?youtubeId ?videoUrl WHERE {
  ?movie wdt:P31 wd:Q11424 ;        # instance of film
         wdt:P1651 ?youtubeId .     # YouTube video ID
  BIND(CONCAT("https://www.youtube.com/watch?v=", ?youtubeId) AS ?videoUrl)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
LIMIT 100

SELECT ?concept ?conceptLabel ?translationCount WHERE {
  ?concept wdt:P31 wd:Q214141 . # instances of sense
  ?sense wdt:P5137 ?concept ;
         wdt:P5972 ?translation . # translations of sense
} GROUP BY ?concept ?conceptLabel
  ORDER BY DESC(COUNT(?translation))
  LIMIT 100

SELECT ?moon ?moonLabel ?planet ?planetLabel ?namesake ?namesakeLabel WHERE {
  ?moon wdt:P397 ?planet .          # moon is a natural satellite of a planet
  ?planet wdt:P31 wd:Q634 .         # planet is a subclass of "planet" (Q634)
  ?moon wdt:P138 ?namesake .        # moon has a namesake
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?monument ?monumentLabel ?personLabel WHERE {
  ?monument wdt:P31 wd:Q4989906 .  # instance of monument
  ?monument wdt:P138 ?person .     # named after a person
  FILTER NOT EXISTS {
    ?monument ?prop ?person .      # no other connection
    FILTER(?prop != wdt:P138)
  }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}

SELECT ?language ?languageLabel WHERE {
  wd:Q55 wdt:P37 ?language.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT DISTINCT ?party ?partyLabel WHERE {
  ?member wdt:P31 wd:Q5 ;
          wdt:P102 ?party ;
          wdt:P3602 wd:Q17020424 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?language ?languageLabel ?followerCount ?date WHERE {
  ?language wdt:P31 wd:Q9143 .  # programming language
  ?language p:P374 ?followerStatement .
  ?followerStatement ps:P374 ?followerCount .
  ?followerStatement pq:P585 ?date .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en" }
}
ORDER BY DESC(?date)

SELECT ?language ?languageLabel ?lemmaCode WHERE {
  ?lemma dct:language ?language .
  ?lemma wikibase:lemma ?lemmaText .
  BIND(STR(?lemmaText) AS ?lemmaCode)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?language ?languageLabel ?lemmaCode

SELECT DISTINCT ?type ?typeLabel WHERE {
  ?item wdt:P195 wd:Q636400 ;
        wdt:P31 ?type .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY ?typeLabel

SELECT ?astrolabe ?astrolabeLabel ?diameter ?date WHERE {
  ?astrolabe wdt:P31 wd:Q128131 ;  # instance of astrolabe
             wdt:P2049 ?diameter ;  # has diameter
             wdt:P571 ?date .       # inception date
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?date

SELECT ?letter ?letterLabel (COUNT(DISTINCT ?alphabet) AS ?count) WHERE {
  ?alphabet wdt:P31 wd:Q9779 ;  # instance of writing system
            wdt:P109 ?letter .   # used letter
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}
GROUP BY ?letter ?letterLabel

SELECT ?descendant ?descendantLabel ?image WHERE {
  ?descendant wdt:P31 wd:Q5 ;
              wdt:P53 ?family .
  ?family wdt:P31 wd:Q134171 .
  ?family wdt:P361 wd:Q121588 .
  OPTIONAL { ?descendant wdt:P18 ?image . }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?firstNameLabel (COUNT(DISTINCT ?person) AS ?count) WHERE {
  ?person wdt:P27 wd:Q142 ;
          wdt:P735 ?firstName ;
          p:P39 ?positionStmt .
  ?positionStmt ps:P39 ?position .
  FILTER(?position IN (wd:Q16707842, wd:Q19842976))
  FILTER NOT EXISTS { ?positionStmt pq:P582 ?endTime }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
GROUP BY ?firstNameLabel
ORDER BY DESC(?count)
LIMIT 10

SELECT ?work ?workLabel ?publicationDate WHERE {
  wd:Q906 wdt:P800 ?work .  # Voltaire wrote these works
  OPTIONAL { ?work wdt:P577 ?publicationDate . }  # publication date
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}

SELECT ?date ?label WHERE {
  { wd:Q9711 wdt:P569 ?date . BIND("birth date" AS ?label) }
  UNION
  { wd:Q9711 wdt:P570 ?date . BIND("death date" AS ?label) }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?date

SELECT DISTINCT ?property ?propertyLabel WHERE {
  ?file wdt:P31 wd:Q235557 .  # instance of file format
  ?file ?property [] .
  ?property a wikibase:Property .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
ORDER BY ?propertyLabel

SELECT ?topic ?topicLabel WHERE {
  ?topic wdt:P31 wd:Q191067 .
  ?article schema:about ?topic .
  ?article schema:isPartOf <https://en.wikipedia.org/> .
  ?article schema:about wd:Q49119 .
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en" }
}

SELECT ?city ?cityLabel ?population WHERE {
  ?city wdt:P31 wd:Q515 ;        # instance of city
        wdt:P17 wd:Q183 ;        # country Germany
        wdt:P1082 ?population .  # population
  FILTER(?population > 50000)
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
ORDER BY DESC(?population)

SELECT ?country ?countryLabel ?isoCode ?flagImage ?fertilityRate WHERE {
  ?country wdt:P31 wd:Q6256 ;           # instance of country
            wdt:P298 ?isoCode .         # ISO 3166-1 alpha-3 code
  OPTIONAL { ?country wdt:P41 ?flagImage . }   # flag image
  OPTIONAL { ?country wdt:P4444 ?fertilityRate . } # total fertility rate
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}

SELECT ?type ?typeLabel (COUNT(?work) AS ?count) WHERE {
  ?work wdt:P31 ?type.
  ?type wdt:P279* wd:Q7725634.
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?type ?typeLabel
ORDER BY DESC(?count)

SELECT ?decade ?placeOfBirth ?placeOfBirthLabel (COUNT(DISTINCT ?winner) AS ?count) WHERE {
  ?winner wdt:P166 wd:Q7191 ; # Nobel Prize
          wdt:P569 ?birthDate . # date of birth
  BIND(YEAR(?birthDate) AS ?year)
  BIND(FLOOR(?year / 10) * 10 AS ?decade)
  ?winner wdt:P19 ?placeOfBirth . # place of birth
  SERVICE wikibase:label { bd:serviceParam wikibase:language "[AUTO_LANGUAGE],en". }
}
GROUP BY ?decade ?placeOfBirth ?placeOfBirthLabel
ORDER BY ?decade
